      tip:'등록 위치: 셀프서비스 → 가게관리 → 운영정보. 변경 즉시 반영되므로 운영 단계·시기에 따라 자유롭게 조정 가능. 즉시할인(#16)과 묶어서 "필터 한 단계 + 즉시할인으로 실결제 매력 가격" 조합을 설계하면 노출과 주문 둘 다 잡습니다.',
