// ──────────────────────────────────
// Export — 5개 플랫폼 통합
// ──────────────────────────────────

export const SECTIONS = {
  baemin:   BAEMIN_SECTIONS,
  coupang:  COUPANG_SECTIONS,
  yogiyo:   YOGIYO_SECTIONS,
  ddanggyo: DDANGGYO_SECTIONS,
  mukkebi:  MUKKEBI_SECTIONS,
};

export const CHECKLIST = {
  baemin:   BAEMIN_CHECKLIST,
  coupang:  COUPANG_CHECKLIST,
  yogiyo:   YOGIYO_CHECKLIST,
  ddanggyo: DDANGGYO_CHECKLIST,
  mukkebi:  MUKKEBI_CHECKLIST,
};

// 각 섹션의 항목 수 자동 계산
PLATFORM_IDS.forEach(pid => {
  const sections  = SECTIONS[pid]  || [];
  const checklist = CHECKLIST[pid] || [];
  sections.forEach(s => {
    s.count = checklist.filter(item => item.section === s.id).length;
  });
});

// ──────────────────────────────────
// 헬퍼 함수
// ──────────────────────────────────

export const getSections   = (platform) => SECTIONS[platform]  || [];
export const getChecklist  = (platform) => CHECKLIST[platform] || [];
export const getItem       = (platform, id) => (CHECKLIST[platform] || []).find(i => i.id === id);
export const getPlatform   = (platformId) => PLATFORMS.find(p => p.id === platformId);
export const getSectionCount = (platform, sectionId) =>
  (CHECKLIST[platform] || []).filter(i => i.section === sectionId).length;
export const getTotalCount = (platform) => (CHECKLIST[platform] || []).length;
